const { withAppBuildGradle } = require("@expo/config-plugins");

// Persists the Android release signing config across `expo prebuild --clean`.
//
// `android/` is gitignored, so a hand-edit to app/build.gradle is lost on the
// next prebuild and release builds silently fall back to the debug key (which
// Play Store rejects). This plugin re-applies the edit every prebuild.
//
// Credentials live in <repo>/credentials/ (gitignored, generated by
// scripts/android-keystore.sh). They are OUTSIDE android/ on purpose:
// `expo prebuild --clean` deletes android/ entirely, which would destroy the
// keystore — and losing it means the app can never be updated on Play Store.
// When the file is absent the release build falls back to the debug key so
// local builds still work.
const SIGNING_BLOCK = `    signingConfigs {
        debug {
            storeFile file('debug.keystore')
            storePassword 'android'
            keyAlias 'androiddebugkey'
            keyPassword 'android'
        }
        // Release signing. Credentials live in android/app/keystore.properties
        // (gitignored with android/). Without it, release falls back to the
        // debug key so local builds still work.
        release {
            // rootProject is android/; credentials/ sits at the repo root.
            def keystorePropsFile = rootProject.file("../credentials/keystore.properties")
            if (keystorePropsFile.exists()) {
                def keystoreProps = new Properties()
                keystoreProps.load(new FileInputStream(keystorePropsFile))
                storeFile file(keystoreProps['storeFile'])
                storePassword keystoreProps['storePassword']
                keyAlias keystoreProps['keyAlias']
                keyPassword keystoreProps['keyPassword']
            } else {
                storeFile file('debug.keystore')
                storePassword 'android'
                keyAlias 'androiddebugkey'
                keyPassword 'android'
            }
        }
    }`;

const DEFAULT_SIGNING_BLOCK = `    signingConfigs {
        debug {
            storeFile file('debug.keystore')
            storePassword 'android'
            keyAlias 'androiddebugkey'
            keyPassword 'android'
        }
    }`;

module.exports = function withAndroidReleaseSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    if (cfg.modResults.language !== "groovy") {
      throw new Error(
        "withAndroidReleaseSigning: expected a Groovy build.gradle",
      );
    }
    let contents = cfg.modResults.contents;

    // 1. Ensure the release signingConfig exists.
    if (!contents.includes("signingConfigs.release")) {
      if (!contents.includes(DEFAULT_SIGNING_BLOCK)) {
        throw new Error(
          "withAndroidReleaseSigning: could not find the default signingConfigs block",
        );
      }
      contents = contents.replace(DEFAULT_SIGNING_BLOCK, SIGNING_BLOCK);
    }

    // 2. Point the release build type at it. Match the `release {` build type
    // specifically — a loose regex also matched `signingConfigs { ... debug {`
    // and rewrote the DEBUG build type instead, leaving release debug-signed.
    contents = contents.replace(
      /(buildTypes \{[\s\S]*?release \{[\s\S]*?)signingConfig signingConfigs\.debug/,
      "$1signingConfig signingConfigs.release",
    );

    cfg.modResults.contents = contents;
    return cfg;
  });
};
